import{_ as a,o as t,c as s,an as n}from"./chunks/framework.CuJewpfc.js";const b=JSON.parse('{"title":"KernelAbstractions extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/kernel-abstractions.md","filePath":"extensions/kernel-abstractions.md","lastUpdated":null}'),r={name:"extensions/kernel-abstractions.md"};function o(i,e,c,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="extension-kernel-abstractions" tabindex="-1">KernelAbstractions extension <a class="header-anchor" href="#extension-kernel-abstractions" aria-label="Permalink to &quot;KernelAbstractions extension {#extension-kernel-abstractions}&quot;">​</a></h1><p><code>ComposableRecurrencesKernelAbstractionsExt</code> is loaded automatically when KernelAbstractions is available alongside ComposableRecurrences; KernelAbstractions loads Adapt, its second trigger.</p><p>It adds the <a href="/previews/PR348/lib/public#ComposableRecurrences.each!"><code>each!</code></a> method for <a href="/previews/PR348/lib/public#ComposableRecurrences.Device"><code>Device</code></a>, which runs each loop as one kernel. Each kernel thread runs its loop body serially, so the kernel receives plain data only, whichever executor the call was made under. It also adds the Adapt.jl rules that carry the coefficient wrappers and built-in modifiers into a kernel, so a launch on any backend adapts the arrays they hold. <a href="/previews/PR348/explanation/adjoints-and-backends#executors">Executors</a> lists what runs on a device.</p>',3)])])}const u=a(r,[["render",o]]);export{b as __pageData,u as default};
